   757|export async function resetMemberPasswordWithToken(email: string, token: string, newPassword: string): Promise<MemberResetResult> {
   758|  const normalizedEmail = email.trim().toLowerCase();
   759|  if (!normalizedEmail || !token || !newPassword) {
