   765|  const store = await readMemberStore();
   766|  const record = Object.values(store).find((m) => m.email === normalizedEmail) as (FallbackMemberRecord & { resetToken?: string; resetTokenExpiresAt?: number }) | undefined;
   767|  if (!record || !record.resetToken || record.resetToken !== token) {
   768|    return { success: false, message: 'Invalid or expired reset token.', deploymentMarker: DEPLOYMENT_MARKER };
   769|  }
   770|  if (!record.resetTokenExpiresAt || record.resetTokenExpiresAt < Date.now()) {
   771|    return { success: false, message: 'Reset token has expired. Please request a new one.', deploymentMarker: DEPLOYMENT_MARKER };
   772|  }
