   774|  record.passwordHash = hashPassword(newPassword, salt);
   775|  record.passwordSalt = salt;
   776|  record.resetToken = undefined;
   777|  record.resetTokenExpiresAt = undefined;
   778|  record.updatedAt = new Date().toISOString();
   779|  store[record.id] = record;
